def get_rss_categories(status=None, is_active=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0482000" if __import__("os").path.isdir("./environment_mix/0482000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur == "":
            raise ValueError("cursor malformed")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("cursor malformed")
            off = int(raw.split(":", 1)[1])
            if off < 0:
                raise ValueError("cursor malformed")
            return off
        except Exception:
            raise ValueError("cursor malformed")

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    started = time.time()
    status_code = "succeeded"
    try:
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be an integer in range 1–200")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "deprecated", "disabled"):
                return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled")
        if is_active is not None and not isinstance(is_active, bool):
            return _err("VALIDATION_ERROR", "is_active must be a boolean")
        if sort is None:
            sort = "sort_order"
        if not isinstance(sort, str) or sort not in ("sort_order", "display_name", "slug", "created_at", "updated_at"):
            return _err("VALIDATION_ERROR", "sort must be one of: sort_order, display_name, slug, created_at, updated_at")
        if order is None:
            order = "asc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc")

        try:
            offset = _parse_cursor(cursor)
        except ValueError as e:
            return _err("VALIDATION_ERROR", str(e))

        cats = _load("rss_categories.json")
        # Business rule: get_rss_categories returns where is_active=true; disabled must not be returned.
        # Optional filters can further restrict.
        filtered = []
        for c in cats:
            if not isinstance(c, dict):
                continue
            if c.get("is_active") is not True:
                continue
            if c.get("status") == "disabled":
                continue
            if status is not None and c.get("status") != status:
                continue
            if is_active is not None and c.get("is_active") != is_active:
                continue
            filtered.append(c)

        reverse = (order == "desc")

        def _key(v):
            x = v.get(sort)
            if sort == "sort_order":
                try:
                    return int(x)
                except Exception:
                    return 0
            return "" if x is None else str(x)

        filtered.sort(key=_key, reverse=reverse)

        total = len(filtered)
        page = filtered[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = _make_cursor(next_offset) if has_more else None

        # Implementation choice: newline-separated slugs (consistent).
        text = "\n".join([str(r.get("slug", "")) for r in page])

        latency_ms = int((time.time() - started) * 1000)
        runs = _load("rss_fetch_runs.json")
        runs.append({
            "id": f"rf_{int(time.time()*1000)}_{len(runs)+1}",
            "category_id": "n/a",
            "requested_max_results": 0,
            "requested_max_summary_length": 0,
            "etag": None,
            "last_modified": None,
            "http_status": None,
            "item_count_fetched": len(page),
            "item_count_upserted": 0,
            "error_message": None,
            "status": status_code,
            "started_at": _now(),
            "finished_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
            "endpoint": "get_rss_categories",
            "latency_ms": latency_ms
        })
        _save("rss_fetch_runs.json", runs)

        return {
            "categories": text,
            "data": page,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "sort": sort,
                "order": order
            }
        }
    except Exception as e:
        latency_ms = int((time.time() - started) * 1000)
        try:
            runs = _load("rss_fetch_runs.json")
            runs.append({
                "id": f"rf_{int(time.time()*1000)}_{len(runs)+1}",
                "category_id": "n/a",
                "requested_max_results": 0,
                "requested_max_summary_length": 0,
                "etag": None,
                "last_modified": None,
                "http_status": None,
                "item_count_fetched": 0,
                "item_count_upserted": 0,
                "error_message": str(e),
                "status": "failed",
                "started_at": _now(),
                "finished_at": _now(),
                "created_at": _now(),
                "updated_at": _now(),
                "endpoint": "get_rss_categories",
                "latency_ms": latency_ms
            })
            _save("rss_fetch_runs.json", runs)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "request failed", detail=str(e))

def get_latest_news(category=None, max_results=None, max_summary_length=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0482000" if __import__("os").path.isdir("./environment_mix/0482000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if isinstance(s, str):
            ss = s[:-1] if s.endswith("Z") else s
            try:
                return datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        return None

    def _truncate(s, n):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        if n is None:
            return s
        if n < 0:
            return s
        return s[:n]

    started = time.time()
    run_row = None
    try:
        if category is None:
            category = "all"
        if not isinstance(category, str) or category.strip() == "":
            return _err("VALIDATION_ERROR", "category must be a non-empty string")
        if max_results is None:
            max_results = -1
        if not isinstance(max_results, int):
            return _err("VALIDATION_ERROR", "max_results must be an integer")
        if max_summary_length is None:
            max_summary_length = 150
        if not isinstance(max_summary_length, int) or max_summary_length < 0:
            return _err("VALIDATION_ERROR", "max_summary_length must be an integer >= 0")

        cats = _load("rss_categories.json")
        cat = None
        for c in cats:
            if isinstance(c, dict) and c.get("slug") == category:
                cat = c
                break
        if cat is None:
            return _err("VALIDATION_ERROR", "category must match an existing rss_categories.slug", category=category)
        if cat.get("status") == "disabled" or cat.get("is_active") is not True:
            return _err("VALIDATION_ERROR", "category is not active", category=category)

        hard_cap = 200
        applied_limit = hard_cap if max_results == -1 else max(0, min(max_results, hard_cap))

        runs = _load("rss_fetch_runs.json")
        run_id = f"rfr_{int(time.time()*1000)}_{len(runs)+1}"
        run_row = {
            "id": run_id,
            "category_id": cat.get("id"),
            "requested_max_results": int(max_results),
            "requested_max_summary_length": int(max_summary_length),
            "etag": None,
            "last_modified": None,
            "http_status": 200,
            "item_count_fetched": 0,
            "item_count_upserted": 0,
            "error_message": None,
            "status": "running",
            "started_at": _now(),
            "finished_at": None,
            "created_at": _now(),
            "updated_at": _now()
        }
        runs.append(run_row)
        _save("rss_fetch_runs.json", runs)

        articles = _load("articles.json")
        joins = _load("article_categories.json")

        # Determine category filter: use designated 'all' category row if slug=all.
        cat_id = cat.get("id")

        allowed_article_ids = set()
        for j in joins:
            if not isinstance(j, dict):
                continue
            if j.get("category_id") == cat_id:
                aid = j.get("article_id")
                if isinstance(aid, str):
                    allowed_article_ids.add(aid)

        selected = []
        for a in articles:
            if not isinstance(a, dict):
                continue
            if a.get("id") not in allowed_article_ids:
                continue
            if a.get("status") != "active":
                continue
            if a.get("language") != "en" or a.get("source") != "cointelegraph_rss":
                continue
            selected.append(a)

        def _k(a):
            dt = _parse_dt(a.get("published_at"))
            return dt if dt is not None else datetime.datetime.min

        selected.sort(key=_k, reverse=True)

        selected = selected[:applied_limit] if applied_limit > 0 else []

        # Presentation-only truncation
        out = []
        for a in selected:
            aa = dict(a)
            aa["summary"] = _truncate(aa.get("summary"), max_summary_length)
            out.append(aa)

        # No external fetch: item_count_upserted always 0 here (still a successful run).
        item_count_fetched = len(out)
        item_count_upserted = 0

        # Finalize run
        runs = _load("rss_fetch_runs.json")
        for r in runs:
            if isinstance(r, dict) and r.get("id") == run_id:
                r["status"] = "succeeded"
                r["item_count_fetched"] = item_count_fetched
                r["item_count_upserted"] = item_count_upserted
                r["finished_at"] = _now()
                r["updated_at"] = _now()
                break
        _save("rss_fetch_runs.json", runs)

        return {
            "category": category,
            "applied_limit": applied_limit,
            "requested_max_results": max_results,
            "requested_max_summary_length": max_summary_length,
            "articles": out,
            "meta": {"count": len(out)}
        }
    except Exception as e:
        try:
            # Mark last run failed if we created one
            if run_row is not None:
                runs = _load("rss_fetch_runs.json")
                for r in runs:
                    if isinstance(r, dict) and r.get("id") == run_row.get("id"):
                        r["status"] = "failed"
                        r["error_message"] = str(e)
                        r["http_status"] = 500
                        r["finished_at"] = _now()
                        r["updated_at"] = _now()
                        break
                _save("rss_fetch_runs.json", runs)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "request failed", detail=str(e))

def get_articles(category_slug=None, status=None, language=None, source=None, published_after=None, published_before=None, limit=None, cursor=None, sort=None, order=None, max_summary_length=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0482000" if __import__("os").path.isdir("./environment_mix/0482000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or s.strip() == "":
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _parse_dt_store(s):
        if not isinstance(s, str):
            return None
        ss = s[:-1] if s.endswith("Z") else s
        try:
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return None

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur == "":
            raise ValueError("cursor malformed")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("cursor malformed")
            off = int(raw.split(":", 1)[1])
            if off < 0:
                raise ValueError("cursor malformed")
            return off
        except Exception:
            raise ValueError("cursor malformed")

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    def _truncate(s, n):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        if n is None:
            return s
        return s[:n]

    started = time.time()
    try:
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be an integer in range 1–200")
        if sort is None:
            sort = "published_at"
        if not isinstance(sort, str) or sort not in ("published_at", "created_at", "updated_at"):
            return _err("VALIDATION_ERROR", "sort must be one of: published_at, created_at, updated_at")
        if order is None:
            order = "desc"
        if not isinstance(order, str) or order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc")
        if status is not None:
            if not isinstance(status, str) or status not in ("active", "removed", "tombstoned"):
                return _err("VALIDATION_ERROR", "status must be one of: active, removed, tombstoned")
        if max_summary_length is not None:
            if not isinstance(max_summary_length, int) or max_summary_length < 0 or max_summary_length > 2000:
                return _err("VALIDATION_ERROR", "max_summary_length must be an integer in range 0–2000")

        dt_after = _parse_dt_rfc3339(published_after)
        if published_after is not None and dt_after is None:
            return _err("VALIDATION_ERROR", "published_after must be an RFC 3339 date-time string")
        dt_before = _parse_dt_rfc3339(published_before)
        if published_before is not None and dt_before is None:
            return _err("VALIDATION_ERROR", "published_before must be an RFC 3339 date-time string")

        try:
            offset = _parse_cursor(cursor)
        except ValueError as e:
            return _err("VALIDATION_ERROR", str(e))

        cats = _load("rss_categories.json")
        slug_to_id = {}
        for c in cats:
            if isinstance(c, dict) and isinstance(c.get("slug"), str) and isinstance(c.get("id"), str):
                slug_to_id[c["slug"]] = c["id"]

        category_id = None
        if category_slug is not None:
            if not isinstance(category_slug, str) or category_slug.strip() == "":
                return _err("VALIDATION_ERROR", "category_slug must be a non-empty string")
            category_id = slug_to_id.get(category_slug)
            if category_id is None:
                # Reads with filters matching nothing return empty set (not error)
                category_id = "__none__"

        articles = _load("articles.json")
        joins = _load("article_categories.json")

        allowed_article_ids = None
        if category_slug is not None:
            allowed_article_ids = set()
            for j in joins:
                if not isinstance(j, dict):
                    continue
                if j.get("category_id") == category_id:
                    aid = j.get("article_id")
                    if isinstance(aid, str):
                        allowed_article_ids.add(aid)

        filtered = []
        for a in articles:
            if not isinstance(a, dict):
                continue
            if allowed_article_ids is not None and a.get("id") not in allowed_article_ids:
                continue
            if status is not None and a.get("status") != status:
                continue
            if language is not None:
                if not isinstance(language, str) or language.strip() == "":
                    return _err("VALIDATION_ERROR", "language must be a non-empty string when provided")
                if a.get("language") != language:
                    continue
            if source is not None:
                if not isinstance(source, str) or source.strip() == "":
                    return _err("VALIDATION_ERROR", "source must be a non-empty string when provided")
                if a.get("source") != source:
                    continue
            padt = _parse_dt_store(a.get("published_at"))
            if dt_after is not None and (padt is None or padt < dt_after):
                continue
            if dt_before is not None and (padt is None or padt > dt_before):
                continue
            filtered.append(a)

        reverse = (order == "desc")

        def _k(a):
            dt = _parse_dt_store(a.get(sort))
            return dt if dt is not None else datetime.datetime.min

        filtered.sort(key=_k, reverse=reverse)

        total = len(filtered)
        page = filtered[offset: offset + limit]
        next_offset = offset + len(page)
        has_more = next_offset < total
        next_cursor = _make_cursor(next_offset) if has_more else None

        out = []
        for a in page:
            aa = dict(a)
            if max_summary_length is not None:
                aa["summary"] = _truncate(aa.get("summary"), max_summary_length)
            out.append(aa)

        latency_ms = int((time.time() - started) * 1000)
        runs = _load("rss_fetch_runs.json")
        runs.append({
            "id": f"rf_{int(time.time()*1000)}_{len(runs)+1}",
            "category_id": "n/a",
            "requested_max_results": 0,
            "requested_max_summary_length": int(max_summary_length or 0),
            "etag": None,
            "last_modified": None,
            "http_status": None,
            "item_count_fetched": len(out),
            "item_count_upserted": 0,
            "error_message": None,
            "status": "succeeded",
            "started_at": _now(),
            "finished_at": _now(),
            "created_at": _now(),
            "updated_at": _now(),
            "endpoint": "get_articles",
            "latency_ms": latency_ms
        })
        _save("rss_fetch_runs.json", runs)

        return {
            "data": out,
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "sort": sort,
                "order": order
            }
        }
    except Exception as e:
        try:
            runs = _load("rss_fetch_runs.json")
            runs.append({
                "id": f"rf_{int(time.time()*1000)}_{len(runs)+1}",
                "category_id": "n/a",
                "requested_max_results": 0,
                "requested_max_summary_length": int(max_summary_length or 0) if isinstance(max_summary_length, int) else 0,
                "etag": None,
                "last_modified": None,
                "http_status": None,
                "item_count_fetched": 0,
                "item_count_upserted": 0,
                "error_message": str(e),
                "status": "failed",
                "started_at": _now(),
                "finished_at": _now(),
                "created_at": _now(),
                "updated_at": _now(),
                "endpoint": "get_articles"
            })
            _save("rss_fetch_runs.json", runs)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "request failed", detail=str(e))

def get_article_by_id(id, max_summary_length=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0482000" if __import__("os").path.isdir("./environment_mix/0482000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    endpoint = "get_article_by_id"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status_str, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - start_t) * 1000)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _append_request_log("error", "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    if max_summary_length is not None:
        if not isinstance(max_summary_length, int) or max_summary_length < 0 or max_summary_length > 2000:
            _append_request_log("error", "VALIDATION_ERROR", "max_summary_length must be an integer between 0 and 2000")
            return _err("VALIDATION_ERROR", "max_summary_length must be an integer between 0 and 2000", field="max_summary_length")

    # Load articles (file may be a list or dict wrapper)
    articles_blob = _load("articles.json")
    if isinstance(articles_blob, dict) and isinstance(articles_blob.get("rows"), list):
        articles = articles_blob["rows"]
        wrapper = articles_blob
    elif isinstance(articles_blob, list):
        articles = articles_blob
        wrapper = None
    else:
        articles = []
        wrapper = None

    target = None
    for a in articles:
        if isinstance(a, dict) and a.get("id") == id:
            target = a
            break

    if not target:
        _append_request_log("error", "NOT_FOUND", "Article not found")
        return _err("NOT_FOUND", "Article not found", id=id)

    # Presentation-only truncation (do not persist)
    out = dict(target)
    if max_summary_length is not None and isinstance(out.get("summary"), str):
        out["summary"] = out["summary"][:max_summary_length]

    _append_request_log("ok", None, None)
    return {"article": out}

def update_article(id, title=None, author=None, summary=None, content_html=None, image_url=None, language=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0482000" if __import__("os").path.isdir("./environment_mix/0482000") else "/app/database")
    def _load(n):
