    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start_t = time.time()
    endpoint = "update_article"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _append_request_log(status_str, error_code=None, error_message=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - start_t) * 1000)
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
            "endpoint": endpoint,
            "status": status_str,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _now_iso(),
        })
        _save("request_logs.json", logs)

    # Validate id
    if not isinstance(id, str) or not id.strip():
        _append_request_log("error", "VALIDATION_ERROR", "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    def _validate_opt_str(v, field, allow_empty=True):
        if v is None:
            return None
        if not isinstance(v, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string", field=field)
        if not allow_empty and not v.strip():
            return _err("VALIDATION_ERROR", f"{field} must be a non-empty string", field=field)
        return None

    # Validate optional fields
    e = _validate_opt_str(title, "title", allow_empty=False) if title is not None else None
    if e:
        _append_request_log("error", e["error"]["code"], e["error"]["message"])
        return e
    for (v, f) in [(author, "author"), (summary, "summary"), (content_html, "content_html"), (image_url, "image_url")]:
        e = _validate_opt_str(v, f, allow_empty=True)
        if e:
            _append_request_log("error", e["error"]["code"], e["error"]["message"])
            return e

    if language is not None:
        if not isinstance(language, str):
            _append_request_log("error", "VALIDATION_ERROR", "language must be a string")
            return _err("VALIDATION_ERROR", "language must be a string", field="language")
        if language != "en":
            _append_request_log("error", "VALIDATION_ERROR", "language must be 'en'")
            return _err("VALIDATION_ERROR", "language must be 'en'", field="language")

    allowed_status = {"active", "removed", "tombstoned"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _append_request_log("error", "VALIDATION_ERROR", "status must be one of: active, removed, tombstoned")
            return _err("VALIDATION_ERROR", "status must be one of: active, removed, tombstoned", field="status")

    # Load articles (file may be list or dict wrapper)
    articles_blob = _load("articles.json")
    if isinstance(articles_blob, dict) and isinstance(articles_blob.get("rows"), list):
        articles = articles_blob["rows"]
        wrapper = articles_blob
    elif isinstance(articles_blob, list):
        articles = articles_blob
        wrapper = None
    else:
        articles = []
        wrapper = None

    idx = None
    for i, a in enumerate(articles):
        if isinstance(a, dict) and a.get("id") == id:
            idx = i
            break
    if idx is None:
        _append_request_log("error", "NOT_FOUND", "Article not found")
        return _err("NOT_FOUND", "Article not found", id=id)

    current = articles[idx]
    updated = dict(current)

    # Status lifecycle transition enforcement
    transitions = {
        "active": {"removed", "tombstoned"},
        "removed": {"active", "tombstoned"},
        "tombstoned": set(),
    }
    if status is not None:
        cur_status = current.get("status")
        if cur_status not in transitions:
            _append_request_log("error", "VALIDATION_ERROR", "Current article status is invalid")
            return _err("VALIDATION_ERROR", "Current article status is invalid", field="status", current_status=cur_status)
        if status != cur_status and status not in transitions[cur_status]:
            _append_request_log("error", "INVALID_TRANSITION", "Status transition not permitted")
            return _err("INVALID_TRANSITION", "Status transition not permitted", from_status=cur_status, to_status=status)
        updated["status"] = status

    # Apply updates
    if title is not None:
        updated["title"] = title
    if author is not None:
        updated["author"] = author
    if summary is not None:
        updated["summary"] = summary
    if content_html is not None:
        updated["content_html"] = content_html
    if image_url is not None:
        updated["image_url"] = image_url
    if language is not None:
        updated["language"] = language

    # Enforce schema constraints that are relevant here
    # canonical_url must remain http-ish, and globally unique; update_article doesn't accept canonical_url, but ensure it's still valid
    cu = updated.get("canonical_url")
    if not isinstance(cu, str) or not cu.startswith("http"):
        _append_request_log("error", "VALIDATION_ERROR", "canonical_url must start with 'http'")
        return _err("VALIDATION_ERROR", "canonical_url must start with 'http'", field="canonical_url")

    # Unique(canonical_url) check (defensive, should already hold)
    for j, a in enumerate(articles):
        if j == idx or not isinstance(a, dict):
            continue
        if a.get("canonical_url") == cu:
            _append_request_log("error", "CONFLICT", "canonical_url already exists")
            return _err("CONFLICT", "canonical_url already exists", field="canonical_url", canonical_url=cu)

    # guid uniqueness when present
    guid = updated.get("guid")
    if guid is not None:
        if not isinstance(guid, str):
            _append_request_log("error", "VALIDATION_ERROR", "guid must be a string when present")
            return _err("VALIDATION_ERROR", "guid must be a string when present", field="guid")
        for j, a in enumerate(articles):
            if j == idx or not isinstance(a, dict):
                continue
            if a.get("guid") == guid:
                _append_request_log("error", "CONFLICT", "guid already exists")
                return _err("CONFLICT", "guid already exists", field="guid", guid=guid)

    # Enforce published_at <= fetched_at if both parseable ISO; do not fail on unparseable legacy strings
    def _parse_iso(s):
        if not isinstance(s, str):
            return None
        try:
            z = s.endswith("Z")
            if z:
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    pa = _parse_iso(updated.get("published_at"))
    fa = _parse_iso(updated.get("fetched_at"))
    if pa and fa and pa > fa:
        _append_request_log("error", "VALIDATION_ERROR", "published_at must be <= fetched_at")
        return _err("VALIDATION_ERROR", "published_at must be <= fetched_at", field="published_at")

    updated["updated_at"] = _now_iso()

    # Persist
    articles[idx] = updated
    if wrapper is not None:
        wrapper["rows"] = articles
        _save("articles.json", wrapper)
    else:
        _save("articles.json", articles)

    _append_request_log("ok", None, None)
    return {"article": updated}

