        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")

    if slug is not None and (not isinstance(slug, str) or not slug.strip()):
        _log("error", "VALIDATION_ERROR", "slug must be a non-empty string")
        return _err("VALIDATION_ERROR", "slug must be a non-empty string", field="slug")
    if display_name is not None and (not isinstance(display_name, str) or not display_name.strip()):
        _log("error", "VALIDATION_ERROR", "display_name must be a non-empty string")
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string", field="display_name")
