            _log("error", "VALIDATION_ERROR", "status must be one of: active, deprecated, disabled")
            return _err("VALIDATION_ERROR", "status must be one of: active, deprecated, disabled",
                        field="status", allowed=["active", "deprecated", "disabled"])

    cats = _load("rss_categories.json")
