        cats = []

    idx = None
    for i, c in enumerate(cats):
        if isinstance(c, dict) and c.get("id") == id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND", "Category not found")
        return _err("NOT_FOUND", "Category not found", id=id)

    cat = cats[idx]
    current_status = cat.get("status")
    transitions = {
        "active": ["deprecated", "disabled"],
        "deprecated": ["active", "disabled"],
        "disabled": ["active"],
    }

    # Uniqueness on slug if changed
    if slug is not None and slug != cat.get("slug"):
        for other in cats:
            if other is cat:
                continue
            if isinstance(other, dict) and other.get("slug") == slug:
                _log("error", "CONFLICT", "slug already exists")
                return _err("CONFLICT", "slug already exists", field="slug", slug=slug)

