                continue
            if isinstance(other, dict) and other.get("rss_url") == rss_url:
                _log("error", "CONFLICT", "rss_url already exists")
                return _err("CONFLICT", "rss_url already exists", field="rss_url", rss_url=rss_url)

    # Enforce status transition if requested and different
    if status is not None and status != current_status:
        if current_status not in transitions or status not in transitions[current_status]:
            _log("error", "INVALID_TRANSITION", f"Illegal status transition {current_status} -> {status}")
            return _err("INVALID_TRANSITION", "Illegal status transition",
                        from_status=current_status, to_status=status)

    changed = False
    for field, val in (("slug", slug), ("display_name", display_name), ("rss_url", rss_url),
                       ("sort_order", sort_order), ("is_active", is_active), ("status", status)):
        if val is not None and cat.get(field) != val:
            cat[field] = val
            changed = True

    # Re-check constraints
    if not isinstance(cat.get("rss_url"), str) or cat.get("rss_url") == "":
        _log("error", "VALIDATION_ERROR", "rss_url must be non-empty")
        return _err("VALIDATION_ERROR", "rss_url must be non-empty", field="rss_url")
    if not isinstance(cat.get("sort_order"), int) or cat.get("sort_order") < 0:
        _log("error", "VALIDATION_ERROR", "sort_order must be an integer >= 0")
        return _err("VALIDATION_ERROR", "sort_order must be an integer >= 0", field="sort_order")
    if cat.get("is_active") is True and cat.get("status") not in ("active", "deprecated"):
        _log("error", "VALIDATION_ERROR", "Active categories cannot have status=disabled")
        return _err("VALIDATION_ERROR", "Active categories cannot have status=disabled",
                    field="status", rule="is_active=true implies status in ('active','deprecated')")

    if changed:
        cat["updated_at"] = _now_iso()
        cats[idx] = cat
        _save("rss_categories.json", cats)

    _log("ok", None, None)
    return {"rss_category": cat}
